import logging


class AttenuatorsRegistryEmpty(Exception):
    """Exception raised when attenuators registry is empty"""
    pass


class AttenuatorsPool(object):
    """Class to keep attenuators loaded from configuration file."""

    def __init__(self):
        self.attenuators_registry = {}

    def register_attenuator(self, name, att_instance):
        """
        Register new attenuator
        :param name: Name of new attenuator from configuration file
        :param att_instance: instance of Attenuator class
        """
        att_dict = {name: att_instance}
        self.attenuators_registry.update(att_dict)
        logging.info('Adding new attenuator: {}'.format(name))

    def get_attenuator(self, name):
        """
        Return attenuator from registry
        :param name: attenuator name
        :return: instance of attenuator
        """
        if not self.attenuators_registry:
            raise AttenuatorsRegistryEmpty('Attenuators Registry is empty!')
        elif name not in self.attenuators_registry:
            raise AttenuatorNotFound('Attenuator {} not found in Attenuators Registry: {}'.format(name, str(self.attenuators_registry)))
        else:
            return self.attenuators_registry[name]


class AttenuatorNotFound(Exception):
    """Exception raised when given attenuator object was not found in attenuators registry"""
    pass
